import sailpoint.object.Identity;
import sailpoint.object.Capability;
import java.util.ArrayList;
// Creates/updates the non-admin test user: BusinessRoleAdministrator only
Identity i = context.getObjectByName(Identity.class, "sbxRoleManager");
if (i == null) {
    i = new Identity();
    i.setName("sbxRoleManager");
}
i.setFirstname("SBX");
i.setLastname("Role Manager");
List caps = new ArrayList();
caps.add(context.getObjectByName(Capability.class, "BusinessRoleAdministrator"));
i.setCapabilities(caps);
i.setPassword("f02xdO27MbiFtzhU");
i.setPasswordExpiration(null);
context.saveObject(i); context.commitTransaction();
return i.getName() + " caps=" + i.getCapabilityManager().getEffectiveCapabilities();
